def cls(unit: str, label: str | None, adjud: dict[str, str] | None = None, sid: str | None = None) -> str:
    if adjud and sid in adjud:
        return adjud[sid]
    if label is None or label in BAD:
        return "invalid"
    if label in UNITS[unit]["catalogue"]:
        return label
    return "other"


